const items = $input.all().slice(0, 8);
const lines = items.map((it, i) => {
  const j = it.json;
  const title = (j.title || '').toString().trim();
  const link = (j.link || j.guid || '').toString().trim();
  const snip = (j.contentSnippet || j.content || j.description || '')
    .toString().replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 220);
  return (i + 1) + '. ' + title + '\n   ' + snip + '\n   ' + link;
}).join('\n');
const today = new Date().toISOString().slice(0, 10);
const prompt = [
  "You are a financial news editor. Based ONLY on the headlines below, write a market-news digest for a Telegram message.",
  "",
  "HEADLINES:",
  lines,
  "",
  "Write the digest in PLAIN TEXT (no markdown symbols like *, _, # and no link syntax):",
  "- First line exactly: 📊 Financial News Digest — " + today,
  "- Then 5 to 7 one-line bullets, each starting with '• ', covering the most important items",
  "- Then a blank line, then 'Bottom line:' and 2-3 sentences on the overall market tone",
  "- Keep it under 3000 characters. Do not invent anything not in the headlines."
].join('\n');
return [{ json: { model: 'qwen3:8b', prompt: prompt } }];
